class Pager:
    def __init__(self, skip: int = 0, limit: int = 20):
        self.skip, self.limit = skip, limit

@app.get('/courses')
def list_courses(pager: Pager = Depends()):   # 类直接当依赖
    return db.query(Course).offset(pager.skip).limit(pager.limit).all()

class AppError(Exception):
    def __init__(self, code: int, msg: str):
        self.code, self.msg = code, msg

@app.exception_handler(AppError)
async def on_app_error(request, exc):
    return JSONResponse(status_code=exc.code, content={'error': exc.msg})

@app.post('/signup', status_code=202)
def signup(payload: Signup, bg: BackgroundTasks):
    bg.add_task(send_welcome_email, payload.email)  # 响应之后执行
    return {'queued': True}
